if(p==='/api/admin/login'&&m==='POST'){const b=await req.json().catch(()=>({}));if(!env.ADMIN_PASSWORD||b.password!==env.ADMIN_PASSWORD)return json({error:'Mot de passe incorrect'},401);const token=await makeToken(env);return json({ok:true,token},200,{'Set-Cookie':`bm_admin=${token}; ${cookieOptions()}`})}
