if(p==='/api/admin/translate'&&m==='POST'){const b=await req.json().catch(()=>({}));try{const [nf,ne,df,de]=await Promise.all([translateOne(b.name,'zh-CN','fr-FR'),translateOne(b.name,'zh-CN','en-GB'),translateOne(b.description,'zh-CN','fr-FR'),translateOne(b.description,'zh-CN','en-GB')]);return json({name_fr:nf,name_en:ne,description_fr:df,description_en:de})}catch{return json({name_fr:'',name_en:'',description_fr:'',description_en:'',warning:'自动翻译服务暂时不可用，请手动填写法语和英语。'})}}
if(p==='/api/admin/products'&&m==='GET'){const{results}=await env.DB.prepare('SELECT * FROM products ORDER BY id DESC').all();return json(results.map(withImages))}
if(p==='/api/admin/products'&&m==='POST'){const b=await req.json();if(!String(b.name||'').trim())return json({error:'商品名称不能为空'},400);const r=await env.DB.prepare(`INSERT INTO products(name,description,name_en,name_zh,description_en,description_zh,price,category,category_en,category_zh,image_key,emoji,stock,active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(b.name||'',b.description||'',b.name_en||'',b.name_zh||b.name||'',b.description_en||'',b.description_zh||'',Number(b.price)||0,b.category||'Maison',b.category_en||'',b.category_zh||'',typeof b.image_key==='string'?b.image_key:'',b.emoji||'🛍️',Number(b.stock)||0,b.active===false?0:1).run();return json({ok:true,id:r.meta.last_row_id})}
