if(p==='/api/admin/banners'&&m==='GET'){const{results}=await env.DB.prepare('SELECT * FROM banners ORDER BY sort_order ASC,id DESC').all();return json(results)}
if(p==='/api/admin/banners'&&m==='POST'){const b=await req.json();if(!b.image_key)return json({error:'请先上传宣传图片'},400);const r=await env.DB.prepare(`INSERT INTO banners(image_key,title,subtitle,title_en,title_zh,subtitle_en,subtitle_zh,button_text,button_text_en,button_text_zh,button_link,sort_order,active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(b.image_key,b.title||b.title_fr||'',b.subtitle||b.subtitle_fr||'',b.title_en||'',b.title_zh||'',b.subtitle_en||'',b.subtitle_zh||'',b.button_text||b.button_text_fr||'Voir les produits',b.button_text_en||'View products',b.button_text_zh||'查看商品',b.button_link||'#products',Number(b.sort_order)||0,b.active===false?0:1).run();return json({ok:true,id:r.meta.last_row_id})}
const bm=p.match(/^\/api\/admin\/banners\/(\d+)$/);if(bm&&m==='PUT'){const b=await req.json();if(!b.image_key)return json({error:'请先上传宣传图片'},400);await env.DB.prepare(`UPDATE banners SET image_key=?,title=?,subtitle=?,title_en=?,title_zh=?,subtitle_en=?,subtitle_zh=?,button_text=?,button_text_en=?,button_text_zh=?,button_link=?,sort_order=?,active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(b.image_key,b.title||b.title_fr||'',b.subtitle||b.subtitle_fr||'',b.title_en||'',b.title_zh||'',b.subtitle_en||'',b.subtitle_zh||'',b.button_text||b.button_text_fr||'Voir les produits',b.button_text_en||'View products',b.button_text_zh||'查看商品',b.button_link||'#products',Number(b.sort_order)||0,b.active===false?0:1,Number(bm[1])).run();return json({ok:true})}if(bm&&m==='DELETE'){await env.DB.prepare('DELETE FROM banners WHERE id=?').bind(Number(bm[1])).run();return json({ok:true})}
